#include "spng.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <png_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    unsigned char *buf = malloc(size);
    fread(buf, 1, size, f);
    fclose(f);

    int ret;
    unsigned char *out = NULL;
    spng_ctx *ctx = spng_ctx_new(0);
    if (!ctx) { free(buf); return 1; }

    ret = spng_set_png_buffer(ctx, buf, size);
    if (ret) goto err;

    spng_set_image_limits(ctx, 200000, 200000);
    spng_set_chunk_limits(ctx, 4 * 1000 * 1000, 8 * 1000 * 1000);
    spng_set_crc_action(ctx, SPNG_CRC_USE, SPNG_CRC_USE);

    size_t out_size;
    if (spng_decoded_image_size(ctx, SPNG_FMT_RGBA8, &out_size)) goto err;
    if (out_size > 80000000) goto err;

    out = malloc(out_size);
    if (!out) goto err;

    if (spng_decode_image(ctx, out, out_size, SPNG_FMT_RGBA8, 0)) goto err;

err:
    spng_ctx_free(ctx);
    free(out);
    free(buf);
    return 0;
}
EOF
